css:
/* ---- strip Frappe's print chrome so the label is the page ---- */
.print-format{padding:0!important;margin:0!important;min-height:0!important;width:auto!important}
.print-format table,.print-format td,.print-format th{border:none!important}

/* ---- the label: 100mm x 50mm, fixed proportions ---- */
.qrl{
  box-sizing:border-box;
  width:100mm; height:50mm;
  display:flex; align-items:center;
  padding:4mm; gap:5mm;
  border:0.8pt solid #000; border-radius:2mm;
  font-family:Helvetica,Arial,sans-serif; color:#000;
  page-break-inside:avoid; overflow:hidden;
}

/* left: QR sized to the label, ID centred beneath it */
.qrl-left{
  flex:0 0 36mm; width:36mm;
  display:flex; flex-direction:column; align-items:center; justify-content:center;
}
.qrl-img{
  width:34mm; height:34mm; display:block;
  image-rendering:pixelated; image-rendering:crisp-edges;
}
.qrl-id{
  width:36mm; text-align:center;
  margin-top:1.2mm; font-family:"Courier New",Courier,monospace;
  font-size:8pt; font-weight:bold; letter-spacing:0.2pt; white-space:nowrap;
}

/* right: everything on one left edge, vertically centred */
.qrl-right{
  flex:1 1 auto; min-width:0;
  display:flex; flex-direction:column; justify-content:center; gap:1.4mm;
}
.qrl-name{
  font-size:11pt; font-weight:bold; line-height:1.15;
  display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical;
  overflow:hidden; word-break:break-word;
}
.qrl-loc{
  align-self:flex-start;
  background:#000; color:#fff;
  padding:0.9mm 2.4mm; border-radius:1mm;
  font-size:9pt; font-weight:bold; letter-spacing:0.6pt; text-transform:uppercase;
  line-height:1;
}
.qrl-meta{width:100%; border-collapse:collapse; font-size:7.5pt; line-height:1.25;}
.qrl-meta th{
  text-align:left; font-weight:normal; color:#555;
  width:19mm; padding:0.3mm 0; vertical-align:top; white-space:nowrap;
}
.qrl-meta td{padding:0.3mm 0; vertical-align:top; word-break:break-word;}

html:
{%- set loc  = doc.location or "" -%}
{%- set cat  = doc.asset_category or "" -%}
{%- set cust = doc.custodian or "" -%}
<div class="qrl">
  <div class="qrl-left">
    <img class="qrl-img" src="/files/qr-{{ doc.name }}.png" alt="{{ doc.name }}">
    <div class="qrl-id">{{ doc.name }}</div>
  </div>
  <div class="qrl-right">
    <div class="qrl-name">{{ doc.asset_name }}</div>
    {% if loc %}<div class="qrl-loc">{{ loc }}</div>{% endif %}
    <table class="qrl-meta">
      {% if cat %}<tr><th>Category</th><td>{{ cat }}</td></tr>{% endif %}
      <tr><th>Company</th><td>{{ doc.company }}</td></tr>
      {% if cust %}<tr><th>Custodian</th><td>{{ cust }}</td></tr>{% endif %}
      {% if doc.purchase_date %}<tr><th>In use from</th><td>{{ frappe.utils.formatdate(doc.available_for_use_date or doc.purchase_date, "dd-MM-yyyy") }}</td></tr>{% endif %}
    </table>
  </div>
</div>
